blocks.code:
.grid-container {
    display: grid;
    grid-template-columns: 1fr 1fr; /* 2 kolom sama lebar */
    grid-template-rows: auto;
    gap: 10px;
}
.grid-item {
    grid-column: span 1;
}

materi.code:
.navbar {
  display: flex;
  justify-content: space-between; /* logo kiri, menu kanan */
  align-items: center;            /* rata tengah vertikal */
  gap: 1rem;
  padding: 0 1rem;
}
.kartu-wrap {
  display: flex;
  flex-wrap: wrap;   /* turun baris saat sempit */
  gap: 16px;
}
.kartu { flex: 1 1 200px; } /* tumbuh, menyusut, lebar dasar 200px */

.halaman {
  display: grid;
  grid-template-columns: 1fr 2fr 1fr;
  gap: 12px;
}
.halaman header,
.halaman footer { grid-column: 1 / -1; }
